def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    sy, sx = [tuple(p) for p in zip(*np.where(g == 6))][0]
    # region reachable from the marker through background (4-connected)
    R = np.zeros((H, W), bool)
    stack = [(sy, sx)]
    seen = {(sy, sx)}
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny, nx = y+dy, x+dx
            if 0 <= ny < H and 0 <= nx < W and (ny, nx) not in seen and g[ny, nx] == bg:
                seen.add((ny, nx)); R[ny, nx] = True; stack.append((ny, nx))
    def near(y, x, M):
        for dy in (-1,0,1):
            for dx in (-1,0,1):
                ny, nx = y+dy, x+dx
                if (dy or dx) and 0 <= ny < H and 0 <= nx < W and M[ny, nx]:
                    return True
        return False
    out = g.copy()
    wall = np.zeros((H, W), bool)
    mask = (g != bg) & (g != 6)
    for comp in components(mask, diagonal=True):
        if not any(near(y, x, R) for y, x in comp):
            for y, x in comp:
                out[y, x] = bg
        elif any(y in (0, H-1) or x in (0, W-1) for y, x in comp):
            for y, x in comp:
                wall[y, x] = True
    emit(out, "Erase wall objects that do not touch the area reachable from the 6.")
    for y in range(H):
        for x in range(W):
            if R[y, x] and (y in (0, H-1) or x in (0, W-1) or near(y, x, wall)):
                out[y, x] = 7
    emit(out, "Trace the outer boundary of the 6's area in 7: grid edge plus border-attached walls.")
    return out
